/** A citation is generated by the document service, never trusted from model output. */
export interface AiCitation {
  sourceId: string
  title: string
  url: string
}

export interface AiDocumentToolDefinition {
  name: string
  description: string
  inputSchema: Record<string, unknown>
}

export interface AiDocumentToolResult {
  data: unknown
  sources?: AiCitation[]
}
